using System.Data;
using System.Security.Cryptography;
using System.Text;
using System.Text.Json;
using DesignStore.Application.Commerce;
using DesignStore.Domain.Catalog;
using DesignStore.Domain.Commerce;
using DesignStore.Infrastructure.Persistence;
using FluentValidation;
using Microsoft.EntityFrameworkCore;
namespace DesignStore.Infrastructure.Commerce;
public sealed class CommerceService(ApplicationDbContext db,IEnumerable<IPaymentService> payments,IValidator<AddToCartRequest> addValidator,IValidator<CheckoutRequest> checkoutValidator):ICommerceService
{
 static string Hash(string token)=>Convert.ToHexString(SHA256.HashData(Encoding.UTF8.GetBytes(token)));
 IQueryable<Cart> CartGraph()=>db.Carts.Include(x=>x.Items).ThenInclude(x=>x.Product).ThenInclude(x=>x.Translations).Include(x=>x.Items).ThenInclude(x=>x.ProductVariant).ThenInclude(x=>x!.Translations).Include(x=>x.Items).ThenInclude(x=>x.Configuration).AsSplitQuery();
 async Task<Cart> CartAsync(string token,Guid? userId,string culture,bool create,CancellationToken ct)
 {
  var hash=Hash(token);Cart? cart=null;
  if(userId.HasValue){cart=await CartGraph().FirstOrDefaultAsync(x=>x.UserId==userId,ct);var anonymous=await CartGraph().FirstOrDefaultAsync(x=>x.TokenHash==hash&&x.UserId==null,ct);if(cart is null&&anonymous is not null){anonymous.UserId=userId;cart=anonymous;}else if(cart is not null&&anonymous is not null&&cart.Id!=anonymous.Id){foreach(var item in anonymous.Items){var existing=cart.Items.FirstOrDefault(x=>x.ProductId==item.ProductId&&x.ProductVariantId==item.ProductVariantId&&x.ConfigurationFingerprint==item.ConfigurationFingerprint);if(existing is null){item.Cart=cart;cart.Items.Add(item);}else existing.Quantity=Math.Min(99,existing.Quantity+item.Quantity);}db.Carts.Remove(anonymous);}}
  cart??=await CartGraph().FirstOrDefaultAsync(x=>x.TokenHash==hash,ct);
  if(cart is null&&!create)throw new KeyNotFoundException("Košík nebyl nalezen.");
  if(cart is null){cart=new Cart{TokenHash=hash,UserId=userId,Culture=culture};db.Carts.Add(cart);}cart.Culture=culture;cart.ExpiresAtUtc=DateTime.UtcNow.AddDays(30);return cart;
 }
 public async Task<CartView> GetCartAsync(string token,Guid? userId,string culture,CancellationToken ct){var cart=await CartAsync(token,userId,culture,true,ct);await Reprice(cart,culture,ct);await db.SaveChangesAsync(ct);return await View(cart,culture,ct);}
 public async Task AddAsync(string token,Guid? userId,string culture,AddToCartRequest r,CancellationToken ct)
 {
  await addValidator.ValidateAndThrowAsync(r,ct);var product=await db.Products.Include(x=>x.Variants).Include(x=>x.Options).ThenInclude(x=>x.Values).FirstOrDefaultAsync(x=>x.Id==r.ProductId,ct)??throw new ValidationException("Produkt neexistuje.");
  if(!product.IsPublished)throw new ValidationException("Produkt není publikovaný.");ProductVariant? variant=null;if(product.HasVariants){variant=product.Variants.FirstOrDefault(x=>x.Id==r.ProductVariantId)??throw new ValidationException("Vyberte platnou variantu.");if(variant.AvailabilityStatus!=AvailabilityStatus.InStock||variant.StockQuantity<1)throw new ValidationException("Variantu nelze vložit do košíku.");}else if(product.AvailabilityStatus!=AvailabilityStatus.InStock||product.StockQuantity<1)throw new ValidationException("Produkt nelze vložit do košíku.");
  var normalized=ValidateConfiguration(product,r.Configuration);var fingerprint=Fingerprint(normalized);var unit=CommerceRules.RoundMoney((variant?.Price??product.BasePrice)+normalized.Sum(x=>x.PriceAdjustment));var cart=await CartAsync(token,userId,culture,true,ct);var existing=cart.Items.FirstOrDefault(x=>x.ProductId==product.Id&&x.ProductVariantId==variant?.Id&&x.ConfigurationFingerprint==fingerprint);if(existing is null){existing=new CartItem{Cart=cart,Product=product,ProductVariant=variant,Quantity=r.Quantity,ConfigurationFingerprint=fingerprint,LastUnitPrice=unit,Configuration=normalized};db.CartItems.Add(existing);}else existing.Quantity=Math.Min(99,existing.Quantity+r.Quantity);await db.SaveChangesAsync(ct);
 }
 static List<CartItemConfiguration> ValidateConfiguration(Product p,List<CartConfigurationInput> inputs){var result=new List<CartItemConfiguration>();foreach(var option in p.Options){var input=inputs.FirstOrDefault(x=>x.ProductOptionId==option.Id);if(option.IsRequired&&input is null)throw new ValidationException("Povinná konfigurace chybí.");if(input is null)continue;ProductOptionValue? value=null;if(input.ProductOptionValueId.HasValue){value=option.Values.FirstOrDefault(x=>x.Id==input.ProductOptionValueId&&x.IsActive)??throw new ValidationException("Neplatná hodnota konfigurace.");}var text=input.CustomText?.Trim();if(!string.IsNullOrEmpty(text)&&(text.Length>(option.MaximumTextLength??500)||text.Contains('<')||text.Contains('>')))throw new ValidationException("Neplatný vlastní text.");result.Add(new CartItemConfiguration{ProductOptionId=option.Id,ProductOptionValueId=value?.Id,CustomText=text,PriceAdjustment=value?.PriceAdjustment??0});}if(inputs.Any(x=>p.Options.All(o=>o.Id!=x.ProductOptionId)))throw new ValidationException("Konfigurace nepatří produktu.");return result;}
 static string Fingerprint(IEnumerable<CartItemConfiguration> c)=>Convert.ToHexString(SHA256.HashData(Encoding.UTF8.GetBytes(string.Join('|',c.OrderBy(x=>x.ProductOptionId).Select(x=>$"{x.ProductOptionId}:{x.ProductOptionValueId}:{x.CustomText}")))));
 public async Task UpdateQuantityAsync(string token,Guid? userId,Guid itemId,int quantity,CancellationToken ct){var c=await CartAsync(token,userId,"cs-CZ",false,ct);var item=c.Items.FirstOrDefault(x=>x.Id==itemId)??throw new KeyNotFoundException();if(quantity<=0)db.CartItems.Remove(item);else if(quantity<=99)item.Quantity=quantity;else throw new ValidationException("Množství je nejvýše 99.");await db.SaveChangesAsync(ct);}
 public async Task RemoveAsync(string token,Guid? userId,Guid itemId,CancellationToken ct)=>await UpdateQuantityAsync(token,userId,itemId,0,ct);
 public async Task ApplyDiscountAsync(string token,Guid? userId,string code,CancellationToken ct){var c=await CartAsync(token,userId,"cs-CZ",false,ct);var normalized=code.Trim().ToUpperInvariant();var d=await ValidDiscount(normalized,ct)??throw new ValidationException("Slevový kód není platný.");c.DiscountCode=d.Code;await db.SaveChangesAsync(ct);}
 async Task<DiscountCode?> ValidDiscount(string? code,CancellationToken ct){if(string.IsNullOrWhiteSpace(code))return null;var now=DateTime.UtcNow;return await db.DiscountCodes.FirstOrDefaultAsync(x=>x.Code==code&&x.IsActive&&(!x.ValidFromUtc.HasValue||x.ValidFromUtc<=now)&&(!x.ValidToUtc.HasValue||x.ValidToUtc>=now)&&(!x.MaximumUses.HasValue||x.UsedCount<x.MaximumUses),ct);}
 async Task Reprice(Cart c,string culture,CancellationToken ct){foreach(var item in c.Items){var p=await db.Products.Include(x=>x.Variants).Include(x=>x.Options).ThenInclude(x=>x.Values).FirstAsync(x=>x.Id==item.ProductId,ct);var v=p.Variants.FirstOrDefault(x=>x.Id==item.ProductVariantId);var adjustments=item.Configuration.Sum(x=>p.Options.SelectMany(o=>o.Values).FirstOrDefault(v=>v.Id==x.ProductOptionValueId)?.PriceAdjustment??0);item.LastUnitPrice=CommerceRules.RoundMoney((v?.Price??p.BasePrice)+adjustments);}}
 async Task<CartView> View(Cart c,string culture,CancellationToken ct){var lines=c.Items.Select(x=>new CartLine(x.Id,x.Product.Translations.FirstOrDefault(t=>t.Culture==culture)?.Name??x.Product.Translations.First().Name,x.ProductVariant?.Translations.FirstOrDefault(t=>t.Culture==culture)?.Name??x.ProductVariant?.Name??"",x.ProductVariant?.Sku??x.Product.Sku,x.Product.MainImageUrl,x.Quantity,x.LastUnitPrice,x.LastUnitPrice*x.Quantity,x.Configuration.OrderBy(cfg=>cfg.ProductOptionId).Select(cfg=>cfg.CustomText??cfg.ProductOptionValueId?.ToString()??string.Empty).ToList())).ToList();var subtotal=CommerceRules.RoundMoney(lines.Sum(x=>x.Total));var d=await ValidDiscount(c.DiscountCode,ct);var discount=d is not null&&subtotal>=d.MinimumOrderValue?CommerceRules.Discount(d.Type,d.Value,subtotal):0;return new CartView(c.Id,lines,subtotal,discount,subtotal-discount,c.Currency,c.DiscountCode);}
 public async Task<CheckoutResult> CheckoutAsync(string token,Guid? userId,CheckoutRequest r,CancellationToken ct)
 {
  await checkoutValidator.ValidateAndThrowAsync(r,ct);var prior=await db.Orders.AsNoTracking().FirstOrDefaultAsync(x=>x.IdempotencyKey==r.IdempotencyKey,ct);if(prior is not null)return new(prior.Id,prior.Number,prior.Total,prior.Currency,prior.PaymentStatus,r.IdempotencyKey);
  await using var tx=await db.Database.BeginTransactionAsync(IsolationLevel.ReadCommitted,ct);var cart=await CartAsync(token,userId,"cs-CZ",false,ct);if(cart.Items.Count==0)throw new ValidationException("Košík je prázdný.");await Reprice(cart,cart.Culture,ct);var cv=await View(cart,cart.Culture,ct);var discount=await ValidDiscount(cart.DiscountCode,ct);var shipping=r.ShippingMethod=="pickup"?0m:250m;var order=new Order{Number=$"WS-{DateTime.UtcNow:yyyyMMdd}-{Guid.NewGuid():N}"[..20].ToUpperInvariant(),IdempotencyKey=r.IdempotencyKey,AccessTokenHash=Hash(r.IdempotencyKey),UserId=userId,Email=r.Email.Trim(),Currency=cart.Currency,Subtotal=cv.Subtotal,DiscountTotal=cv.Discount,ShippingTotal=shipping,Total=CommerceRules.RoundMoney(cv.Total+shipping),DiscountCode=discount?.Code,ShippingMethod=r.ShippingMethod};
  foreach(var ci in cart.Items){var p=await db.Products.Include(x=>x.Translations).Include(x=>x.Variants).ThenInclude(x=>x.Translations).Include(x=>x.Options).ThenInclude(x=>x.Translations).Include(x=>x.Options).ThenInclude(x=>x.Values).ThenInclude(x=>x.Translations).FirstAsync(x=>x.Id==ci.ProductId,ct);var v=p.Variants.FirstOrDefault(x=>x.Id==ci.ProductVariantId);if(!p.IsPublished)throw new ValidationException("Produkt již není dostupný.");int previous;if(v is not null){previous=v.StockQuantity;var affected=await db.ProductVariants.Where(x=>x.Id==v.Id&&x.AvailabilityStatus==AvailabilityStatus.InStock&&x.StockQuantity>=ci.Quantity).ExecuteUpdateAsync(s=>s.SetProperty(x=>x.StockQuantity,x=>x.StockQuantity-ci.Quantity),ct);if(affected!=1)throw new ValidationException("Varianta již není skladem v požadovaném množství.");}else{previous=p.StockQuantity;var affected=await db.Products.Where(x=>x.Id==p.Id&&x.IsPublished&&x.AvailabilityStatus==AvailabilityStatus.InStock&&x.StockQuantity>=ci.Quantity).ExecuteUpdateAsync(s=>s.SetProperty(x=>x.StockQuantity,x=>x.StockQuantity-ci.Quantity),ct);if(affected!=1)throw new ValidationException("Produkt již není skladem v požadovaném množství.");}
   var name=p.Translations.FirstOrDefault(x=>x.Culture==cart.Culture)?.Name??p.Translations.First().Name;var variantName=v?.Translations.FirstOrDefault(x=>x.Culture==cart.Culture)?.Name??v?.Name??"";var gross=CommerceRules.RoundMoney(ci.LastUnitPrice*ci.Quantity);var lineDiscount=cv.Subtotal==0?0:CommerceRules.RoundMoney(cv.Discount*gross/cv.Subtotal);var taxable=gross-lineDiscount;var tax=CommerceRules.RoundMoney(taxable*p.VatRate/(100+p.VatRate));var oi=new OrderItem{Order=order,ProductId=p.Id,ProductVariantId=v?.Id,ProductName=name,VariantName=variantName,Sku=v?.Sku??p.Sku,ImageUrl=p.MainImageUrl,Quantity=ci.Quantity,UnitPrice=ci.LastUnitPrice,DiscountAmount=lineDiscount,VatRate=p.VatRate,TaxAmount=tax,LineTotal=taxable,Currency=cart.Currency};foreach(var cfg in ci.Configuration){var option=p.Options.First(x=>x.Id==cfg.ProductOptionId);var value=option.Values.FirstOrDefault(x=>x.Id==cfg.ProductOptionValueId);oi.Configuration.Add(new OrderItemConfiguration{OptionName=option.Translations.FirstOrDefault(x=>x.Culture==cart.Culture)?.Name??option.Translations.First().Name,Value=cfg.CustomText??value?.Translations.FirstOrDefault(x=>x.Culture==cart.Culture)?.Name??value?.Translations.First().Name??"",PriceAdjustment=cfg.PriceAdjustment});}order.Items.Add(oi);order.TaxTotal+=tax;db.InventoryMovements.Add(new InventoryMovement{ProductId=v is null?p.Id:null,ProductVariantId=v?.Id,OrderId=order.Id,Type=InventoryMovementType.Sale,QuantityChange=-ci.Quantity,PreviousQuantity=previous,NewQuantity=previous-ci.Quantity,Reason="Checkout"});if(previous-ci.Quantity==0){if(v is not null)await db.ProductVariants.Where(x=>x.Id==v.Id).ExecuteUpdateAsync(s=>s.SetProperty(x=>x.AvailabilityStatus,v.CanBeMadeToOrder?AvailabilityStatus.MadeToOrder:AvailabilityStatus.Unavailable),ct);else await db.Products.Where(x=>x.Id==p.Id).ExecuteUpdateAsync(s=>s.SetProperty(x=>x.AvailabilityStatus,p.CanBeMadeToOrder?AvailabilityStatus.MadeToOrder:AvailabilityStatus.Unavailable),ct);}}
  order.TaxTotal=CommerceRules.RoundMoney(order.TaxTotal);var bill=r.BillingAddress;var ship=r.UseBillingAsShipping?bill:r.ShippingAddress;order.Addresses.Add(ToAddress(order,bill,AddressType.Billing));order.Addresses.Add(ToAddress(order,ship,AddressType.Shipping));order.StatusHistory.Add(new OrderStatusHistory{Order=order,NewStatus=OrderStatus.PendingPayment,Reason="Objednávka vytvořena"});var provider=payments.Single(x=>x.Method==r.PaymentMethod);var pr=await provider.CreateAsync(order.Number,order.Total,order.Currency,r.IdempotencyKey,ct);order.PaymentStatus=pr.Status;if(pr.Status==PaymentStatus.Paid)order.Status=OrderStatus.Paid;order.Shipments.Add(new Shipment{Order=order,Carrier=r.ShippingMethod=="pickup"?"Wild Spirit":"Contract carrier",Service=r.ShippingMethod,Price=shipping});order.Payments.Add(new Payment{Order=order,Method=r.PaymentMethod,Status=pr.Status,Amount=order.Total,Currency=order.Currency,ProviderReference=pr.Reference,ExternalEventId=pr.ExternalEventId,PaidAtUtc=pr.Status==PaymentStatus.Paid?DateTime.UtcNow:null});db.Orders.Add(order);if(discount is not null)discount.UsedCount++;db.OutboxMessages.Add(new OutboxMessage{Type="OrderConfirmation",Payload=JsonSerializer.Serialize(new{order.Number,order.Email,order.Total,order.Currency})});db.CartItems.RemoveRange(cart.Items);await db.SaveChangesAsync(ct);await tx.CommitAsync(ct);return new(order.Id,order.Number,order.Total,order.Currency,order.PaymentStatus,r.IdempotencyKey);
 }
 static OrderAddress ToAddress(Order o,AddressInput a,AddressType type)=>new(){Order=o,Type=type,FullName=a.FullName,Company=a.Company,Street=a.Street,City=a.City,PostalCode=a.PostalCode,CountryCode=a.CountryCode,Phone=a.Phone};
 public async Task<OrderDetail?> GetCustomerOrderAsync(Guid id,string accessToken,CancellationToken ct){if(string.IsNullOrWhiteSpace(accessToken))return null;var valid=await db.Orders.AsNoTracking().AnyAsync(x=>x.Id==id&&x.AccessTokenHash==Hash(accessToken),ct);return valid?await GetOrderAsync(id,ct):null;}
 public async Task<IReadOnlyList<OrderListItem>> GetOrdersAsync(CancellationToken ct)=>await db.Orders.AsNoTracking().OrderByDescending(x=>x.CreatedAtUtc).Take(200).Select(x=>new OrderListItem(x.Id,x.Number,x.Email,x.CreatedAtUtc,x.Status,x.PaymentStatus,x.Total,x.Currency)).ToListAsync(ct);
 public async Task<OrderDetail?> GetOrderAsync(Guid id,CancellationToken ct)=>await db.Orders.AsNoTracking().Where(x=>x.Id==id).Select(x=>new OrderDetail(x.Id,x.Number,x.Email,x.Status,x.PaymentStatus,x.Subtotal,x.DiscountTotal,x.ShippingTotal,x.TaxTotal,x.Total,x.Currency,x.Items.Select(i=>new CartLine(i.Id,i.ProductName,i.VariantName,i.Sku,i.ImageUrl,i.Quantity,i.UnitPrice,i.LineTotal,i.Configuration.Select(c=>c.OptionName+": "+c.Value).ToList())).ToList(),x.StatusHistory.OrderBy(h=>h.CreatedAtUtc).Select(h=>h.CreatedAtUtc+" "+h.NewStatus+" "+h.Reason).ToList())).FirstOrDefaultAsync(ct);
 public async Task ChangeStatusAsync(Guid id,OrderStatus status,string? actor,CancellationToken ct){var o=await db.Orders.Include(x=>x.StatusHistory).FirstOrDefaultAsync(x=>x.Id==id,ct)??throw new KeyNotFoundException();if(o.Status==status)return;if(!CommerceRules.CanTransition(o.Status,status))throw new ValidationException("Neplatná změna stavu.");if(status==OrderStatus.Cancelled){await CancelAsync(id,actor,ct);return;}var old=o.Status;o.Status=status;var history=new OrderStatusHistory{Order=o,PreviousStatus=old,NewStatus=status,Reason="Administrace",CreatedBy=actor};o.StatusHistory.Add(history);db.Add(history);await db.SaveChangesAsync(ct);}
 public async Task CancelAsync(Guid id,string? actor,CancellationToken ct){await using var tx=await db.Database.BeginTransactionAsync(IsolationLevel.ReadCommitted,ct);var o=await db.Orders.Include(x=>x.Items).Include(x=>x.StatusHistory).FirstOrDefaultAsync(x=>x.Id==id,ct)??throw new KeyNotFoundException();if(o.StockReturnedAtUtc.HasValue){await tx.CommitAsync(ct);return;}if(o.Status is OrderStatus.Shipped or OrderStatus.Completed)throw new ValidationException("Odeslanou objednávku nelze takto zrušit.");foreach(var i in o.Items){if(i.ProductVariantId.HasValue){var before=await db.ProductVariants.Where(x=>x.Id==i.ProductVariantId).Select(x=>x.StockQuantity).SingleAsync(ct);await db.ProductVariants.Where(x=>x.Id==i.ProductVariantId).ExecuteUpdateAsync(s=>s.SetProperty(x=>x.StockQuantity,x=>x.StockQuantity+i.Quantity).SetProperty(x=>x.AvailabilityStatus,AvailabilityStatus.InStock),ct);db.InventoryMovements.Add(new InventoryMovement{ProductVariantId=i.ProductVariantId,OrderId=o.Id,Type=InventoryMovementType.Return,QuantityChange=i.Quantity,PreviousQuantity=before,NewQuantity=before+i.Quantity,Reason="Storno objednávky",CreatedBy=actor});}else if(i.ProductId.HasValue){var before=await db.Products.Where(x=>x.Id==i.ProductId).Select(x=>x.StockQuantity).SingleAsync(ct);await db.Products.Where(x=>x.Id==i.ProductId).ExecuteUpdateAsync(s=>s.SetProperty(x=>x.StockQuantity,x=>x.StockQuantity+i.Quantity).SetProperty(x=>x.AvailabilityStatus,AvailabilityStatus.InStock),ct);db.InventoryMovements.Add(new InventoryMovement{ProductId=i.ProductId,OrderId=o.Id,Type=InventoryMovementType.Return,QuantityChange=i.Quantity,PreviousQuantity=before,NewQuantity=before+i.Quantity,Reason="Storno objednávky",CreatedBy=actor});}}var old=o.Status;o.Status=OrderStatus.Cancelled;o.CancelledAtUtc=DateTime.UtcNow;o.StockReturnedAtUtc=DateTime.UtcNow;var history=new OrderStatusHistory{Order=o,PreviousStatus=old,NewStatus=OrderStatus.Cancelled,Reason="Storno",CreatedBy=actor};o.StatusHistory.Add(history);db.Add(history);await db.SaveChangesAsync(ct);await tx.CommitAsync(ct);}
}
